preConditionHook:
// A fresh high 1 that follows a completed high 1 / high 2 sequence
// without an intervening deeper pullback. Brooks: 'after a series of winning
// trades, be suspicious of renewed strength without first seeing a larger
// pullback -- it might be a trap setting up.' Used NEGATED with the
// per-placement toggle it is the filter he actually states ('it is wise to
// wait'), so one rule gives both readings.
//
// THE COUNTER IS THE SETTLED ONE (Ranges ch17, R17-01), inlined here as
// everywhere -- see HighLowBarCount for the full commentary. This rule was
// mined as research grade because it looked to need a memory of prior setup
// TYPES; under the settled counter it does not. The sequence high 1 (,high 1),
// high 2, and a further high 1 IS the counter reaching at least 2, resetting on
// a fresh N-bar high, and re-advancing to 1, so ONE latched integer covers it.
//
// THE LATCH: prevCycleHigh is written at the reset, and only when the count
// it is replacing was non-zero. A run of consecutive fresh N-bar highs would
// otherwise overwrite the memory with 0 on its second bar and lose it. Since
// the count only ever rises within a cycle, its value at the reset IS that
// cycle's maximum.
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)resetLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
advHigh = false;
advLow = false;
if (el_gt(close[0], priorHigh)) {
    if (highCount > 0) prevCycleHigh = highCount;
    highCount = 0;
} else {
    if (el_lt(low[0], minLowSince)) minLowSince = low[0];
    if (el_gt(high[0], high[1]) && (highCount == 0 || el_lt(minLowSince, signalLow))) {
        highCount = highCount + 1;
        if (highCount > 4) highCount = 4;
        signalLow = low[0];
        minLowSince = low[0];
        advHigh = true;
    }
}
if (el_lt(close[0], priorLow)) {
    if (lowCount > 0) prevCycleLow = lowCount;
    lowCount = 0;
} else {
    if (el_gt(high[0], maxHighSince)) maxHighSince = high[0];
    if (el_lt(low[0], low[1]) && (lowCount == 0 || el_gt(maxHighSince, signalHigh))) {
        lowCount = lowCount + 1;
        if (lowCount > 4) lowCount = 4;
        signalHigh = high[0];
        maxHighSince = high[0];
        advLow = true;
    }
}
